dashboard.definition:
{
    "title": "Bettenmanagement",
    "description": "Bettenmanagement: Belegung und freie Betten je Station, Aufnahmen und Entlassungen",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Haus",
            "options": {
                "items": [
                    {
                        "label": "Alle Haeuser",
                        "value": "*"
                    },
                    {
                        "label": "Haus A - Innere Medizin",
                        "value": "A"
                    },
                    {
                        "label": "Haus B - Chirurgisches Zentrum",
                        "value": "B"
                    },
                    {
                        "label": "Haus C - Akut- und Intensivzentrum",
                        "value": "C"
                    },
                    {
                        "label": "Haus D - Frauen, Kind und Psyche",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_beds": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:kis:beds\" department=\"$dept$\" building=\"$building$\" earliest=-15m\n| stats latest(beds_total) as beds_total latest(occupied) as occupied latest(free) as free latest(cleaning) as cleaning latest(blocked) as blocked latest(isolation) as isolation latest(occupancy_pct) as occupancy_pct latest(floor) as floor latest(ward_name) as ward_name latest(status) as status latest(planned_discharges_today) as planned by ward building department department_name",
                "enableSmartSources": true
            },
            "name": "Bettenstatus je Station"
        },
        "ds_k_total": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(beds_total) as Betten"
            }
        },
        "ds_k_free": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(free) as \"Freie Betten\""
            }
        },
        "ds_k_clean": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(cleaning) as \"In Reinigung\""
            }
        },
        "ds_k_iso": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| stats sum(isolation) as Isolation"
            }
        },
        "ds_k_full": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| where free=0 | stats count as \"Volle Stationen\""
            }
        },
        "ds_k_occ": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_metrics department=\"$dept$\" building=\"$building$\" span=15m\n| eval \"Belegung %\"=round(100 * o / t, 1) | fields _time \"Belegung %\"",
                "enableSmartSources": true
            }
        },
        "ds_dept_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(sakh.beds.occupied) as o sum(sakh.beds.beds_total) as t WHERE index=demo_sakh_metrics department=\"$dept$\" building=\"$building$\" BY department span=15m\n| eval pct=round(100 * o / t, 1)\n| timechart span=15m avg(pct) by department limit=0",
                "enableSmartSources": true
            },
            "name": "Belegung je Abteilung"
        },
        "ds_heat": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_sakh_metrics metric_name=\"sakh.beds.occupancy_pct\" department=\"$dept$\" building=\"$building$\" BY ward span=15m\n| timechart span=15m limit=0 avg(value) by ward",
                "enableSmartSources": true
            },
            "name": "Belegung je Station"
        },
        "ds_free_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(_value) as free WHERE index=demo_sakh_metrics metric_name=\"sakh.beds.free\" department=\"$dept$\" building=\"$building$\" BY building span=15m\n| eval building=\"Haus \".building | timechart span=15m avg(free) by building",
                "enableSmartSources": true
            }
        },
        "ds_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_beds",
                "query": "| eval Station=ward.\" – \".ward_name, Belegung=round(occupancy_pct, 1)\n| sort - Belegung\n| table Station department building beds_total occupied free cleaning blocked isolation planned Belegung status\n| rename department as Abteilung building as Haus beds_total as Betten occupied as Belegt free as Frei cleaning as Reinigung blocked as Gesperrt isolation as Isolation planned as \"Entlassungen geplant\" status as Status"
            }
        },
        "ds_adt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:kis:adt\" department=\"$dept$\" building=\"$building$\" (event_type=A01 OR event_type=A03 OR event_type=A02)\n| timechart span=30m count by event_name",
                "enableSmartSources": true
            },
            "name": "Aufnahmen / Entlassungen"
        },
        "ds_adt_dept": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:kis:adt\" event_type=A01 department=\"$dept$\" building=\"$building$\"\n| stats count as Aufnahmen by department | sort - Aufnahmen",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_care_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_nav_diag": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_diag.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_lab",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_medtech": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_medtech.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_medtech",
                        "tokens": [],
