            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_or",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_sub_kis_icu": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/sub_kis_icu.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_icu",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_total"
            },
            "options": {
                "majorColor": "#34e2a0",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_free"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 15,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 15,
                        "to": 40,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 40,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_occ"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 88,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 88,
                        "to": 95,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 95,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_full"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 3,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_clean"
            },
            "options": {
                "majorColor": "#22d3ee",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_iso"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 20,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 20,
                        "to": 40,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 40,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "kis_studio.hospital_map",
            "dataSources": {
                "primary": "ds_beds"
            },
            "options": {
                "drillField": "department",
                "drilldownToken": "dept"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "dept",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "kis_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 88,
                "crit": 95,
                "unit": "%",
                "maxSeries": 40,
                "decimals": 0
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_dept_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "yAxisMin": 40,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.area",
            "dataSources": {
                "primary": "ds_free_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "stackMode": "stacked",
                "areaOpacity": 0.35
            }
        },
        "viz_11": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_adt"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_12": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_adt_dept"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ]
            }
        },
        "viz_13": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 14,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Belegung": {
                        "rowBackgroundColors": "> table | seriesByName(\"Belegung\") | rangeValue(range_2)"
                    },
                    "Status": {
                        "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    },
                    {
                        "match": "kritisch",
                        "value": "#5a1426"
                    },
                    {
                        "match": "voll",
                        "value": "#5a1426"
                    },
                    {
                        "match": "gestoppt",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Gesperrt",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Offline",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Fehler",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Vulnerable",
                        "value": "#5a1426"
                    },
                    {
                        "match": "ueberfaellig",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Rettungsstopp",
                        "value": "#5a1426"
                    },
                    {
                        "match": "unterbesetzt",
                        "value": "#5a1426"
                    },
                    {
                        "match": "niedrig",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "angespannt",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Stau",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Warning",
                        "value": "#4d3a08"
                    },
